-- Generated by ekos-lakehouse (RFC 0195): `count_of_c_order_id` in gold__orders_per_customer reconciles to silver.
with mart as (
    select sum("count_of_c_order_id") as v from {{ ref('gold__orders_per_customer') }}
),

silver as (
    select count(*) as v
    from {{ ref('ADEMPIERE__C_ORDER') }} as "C_ORDER"
    left join {{ ref('ADEMPIERE__C_BPARTNER') }} as "C_BPARTNER"
        on "C_ORDER"."C_BPARTNER_ID" = "C_BPARTNER"."C_BPARTNER_ID"
    where "C_ORDER"."ISACTIVE" = true
        and "C_ORDER"."DOCSTATUS" = 'CO'
)

select mart.v as mart_total, silver.v as silver_total
from mart, silver
where mart.v is distinct from silver.v
